"""
client - Stellt die Funktion connect_to_db() fuer MariaDB-Verbindungen bereit.
"""

import logging
from dataclasses import dataclass

import mariadb

from ..config_service import get_database_config

logger = logging.getLogger(__name__)

DATABASE = "dbm_lesermarkt"


@dataclass(frozen=True)
class DbCredentials:
    """Explizite Zugangsdaten fuer eine MariaDB-Verbindung.

    Attributes:
        host: Datenbankserver, z. B. "db.example.local".
        user: Datenbankbenutzer.
        password: Datenbankpasswort im Klartext zur Laufzeit.
        port: Optionaler Datenbankport, Standard 3306.
    """

    host: str
    user: str
    password: str
    port: int | str = 3306


def _normalize_connection_values(credentials: DbCredentials | None) -> tuple[str, str, str, int]:
    """Ermittelt und validiert konkrete Verbindungswerte."""
    host: str | None
    user: str | None
    password: str | None
    port: int | str

    if credentials is not None:
        host = credentials.host
        user = credentials.user
        password = credentials.password
        port = credentials.port
    else:
        db_config = get_database_config()
        host = db_config.host
        user = db_config.user
        password = db_config.password
        port = db_config.port

    missing_fields = [
        name
        for name, value in {
            "host": host,
            "user": user,
            "password": password,
        }.items()
        if not value
    ]
    if missing_fields:
        raise ValueError("Datenbank-Credentials unvollstaendig: " + ", ".join(missing_fields))

    if host is None or user is None or password is None:
        raise ValueError("Datenbank-Credentials unvollstaendig: host, user, password")

    return host, user, password, int(port)


def connect_to_db(
    database: str = DATABASE,
    credentials: DbCredentials | None = None,
) -> mariadb.connections.Connection:
    """Stellt eine Verbindung zur angegebenen MariaDB-Datenbank her.

    Args:
        database: Der Name der Datenbank, zu der eine Verbindung hergestellt werden soll.
        credentials: Optionale direkte Zugangsdaten. Wenn nicht gesetzt,
            werden die Werte aus constants/.env verwendet.

    Returns:
        Eine MariaDB-Verbindungsinstanz.

    Raises:
        ValueError: Wenn Zugangsdaten unvollstaendig oder der Port ungueltig sind.
        mariadb.Error: Bei Verbindungsfehlern.
    """
    host, user, password, port = _normalize_connection_values(credentials)

    try:
        return mariadb.connect(host=host, user=user, password=password, port=port, database=database)
    except mariadb.Error as exc:
        logger.error("Datenbankverbindungsfehler: %s", exc, exc_info=True)
        raise
